import { stat as stat4 } from "node:fs/promises";

// ../../apps/core/src/ai-tool/getMediaMetadataResponse.ts
function parseMediaIdString(id) {
  const n = Number.parseInt(id, 10);
  return Number.isFinite(n) ? n : 0;
}
function mapTvShowToResponse(tv) {
  return {
    source: tv.database ?? "TVDB",
    id: parseMediaIdString(tv.id),
    name: tv.name,
    seasons: tv.seasons?.map((season) => ({
      seasonNumber: season.season,
      seasonName: season.name,
      episodes: season.episodes?.map((ep) => ({
        seasonNumber: ep.season,
        episodeNumber: ep.episode,
        episodeName: ep.name
      })) ?? []
    })) ?? []
  };
}
function mapTvdbMovieToResponse(m) {
  return {
    tvdbId: parseMediaIdString(m.id),
    name: m.name,
    database: m.database
  };
}
function createBaseGetMediaMetadataData(mediaFolderPath) {
  return {
    mediaFolderPath: Path.toPlatformPath(mediaFolderPath),
    type: "tvshow-folder"
  };
}
function fillMediaMetadataResponseData(metadata, posixPath) {
  const data = {
    mediaFolderPath: Path.toPlatformPath(metadata.mediaFolderPath || posixPath),
    type: metadata.type || "tvshow-folder"
  };
  if (data.type === "tvshow-folder") {
    if (metadata.tvShow) {
      data.tvShow = mapTvShowToResponse(metadata.tvShow);
    } else {
      data.tvShow = GET_MEDIA_METADATA_UNRECOGNIZED;
    }
  } else if (data.type === "movie-folder") {
    if (metadata.movie) {
      if (metadata.movie.database === "TMDB") {
        const tmdbId = parseMediaIdString(metadata.movie.id);
        data.tmdbMovie = {
          tmdbId,
          title: metadata.movie.name,
          originalTitle: metadata.movie.name,
          overview: "",
          releaseDate: metadata.movie.airDate ?? "",
          posterPath: null
        };
        data.tvdbMovie = GET_MEDIA_METADATA_UNRECOGNIZED;
      } else {
        data.tvdbMovie = mapTvdbMovieToResponse(metadata.movie);
        data.tmdbMovie = GET_MEDIA_METADATA_UNRECOGNIZED;
      }
    } else {
      data.tmdbMovie = GET_MEDIA_METADATA_UNRECOGNIZED;
      data.tvdbMovie = GET_MEDIA_METADATA_UNRECOGNIZED;
    }
  }
  return data;
}

// src/mediaMetadataCache.ts
import { mkdir as mkdir2, readFile as readFile2, unlink, writeFile as writeFile2 } from "node:fs/promises";
import path from "node:path";
function metadataCacheFilePath(appDataDir, folderPathInPosix) {
  const filename = folderPathInPosix.replace(/[\/\\:?*|<>"]/g, "_");
  return path.join(appDataDir, "metadata", `${filename}.json`);
}
async function readMediaMetadataCache(appDataDir, mediaFolderPath) {
  const folderPathInPosix = Path.posix(mediaFolderPath);
  const filePath = metadataCacheFilePath(appDataDir, folderPathInPosix);
  try {
    const content = await readFile2(filePath, "utf-8");
    return JSON.parse(content);
  } catch {
    return null;
  }
}
async function writeMediaMetadataCache(appDataDir, mediaMetadata) {
  if (!mediaMetadata.mediaFolderPath) {
    throw new Error("Media folder path is required");
  }
  const metadataDir = path.join(appDataDir, "metadata");
  await mkdir2(metadataDir, { recursive: true });
  const filePath = metadataCacheFilePath(appDataDir, Path.posix(mediaMetadata.mediaFolderPath));
  await writeFile2(filePath, JSON.stringify(mediaMetadata, null, 2), "utf-8");
}
async function deleteMediaMetadataCache(appDataDir, mediaFolderPath) {
  const filePath = metadataCacheFilePath(appDataDir, Path.posix(mediaFolderPath));
  try {
    await unlink(filePath);
  } catch (error) {
    const code = error.code;
    if (code !== "ENOENT") {
      throw error;
    }
  }
}

// src/tools/getMediaMetadata.ts
async function executeGetMediaMetadata(params, userConfig, appDataDir, abortSignal) {
  if (abortSignal?.aborted) {
    throw new Error("Request was aborted");
  }
  const pathCheck = requireNonEmptyString(params.mediaFolderPath, "mediaFolderPath");
  if (typeof pathCheck !== "string") {
    return {
      ...createBaseGetMediaMetadataData(""),
      error: pathCheck.error
    };
  }
  const baseData = createBaseGetMediaMetadataData(pathCheck);
  if (!isMediaFolderManagedFromConfig(userConfig, pathCheck)) {
    return { ...baseData, error: GET_MEDIA_METADATA_NOT_MANAGED };
  }
  try {
    const normalizedPath = Path.toPlatformPath(pathCheck);
    try {
      const stats = await stat4(normalizedPath);
      if (!stats.isDirectory()) {
        return { ...baseData, error: GET_MEDIA_METADATA_NOT_DIRECTORY };
      }
    } catch (error) {
      if (error.code === "ENOENT") {
        return { ...baseData, error: GET_MEDIA_METADATA_FOLDER_NOT_FOUND };
      }
      throw error;
    }
    const posixPath = Path.posix(pathCheck);
    const metadata = await readMediaMetadataCache(appDataDir, posixPath);
    if (!metadata) {
      return { ...baseData, error: GET_MEDIA_METADATA_NO_CACHE };
    }
    return fillMediaMetadataResponseData(metadata, posixPath);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Error reading media metadata: ${message}`);
  }
}
function isMediaFolderManagedFromConfig(userConfig, mediaFolderPath) {
  const targetPlatform = Path.toPlatformPath(mediaFolderPath);
  const targetPosix = Path.posix(mediaFolderPath);
  return (userConfig.folders ?? []).some((folder) => {
    return Path.toPlatformPath(folder) === targetPlatform || Path.posix(folder) === targetPosix;
  });
}
function buildGetMediaMetadataTool(userConfig, appDataDir, abortSignal) {
  return {
    description: GET_MEDIA_METADATA_DESCRIPTION,
    inputSchema: getMediaMetadataInputSchema,
    outputSchema: getMediaMetadataToolOutputSchema,
    execute: async (args) => {
      const params = args ?? {};
      return executeGetMediaMetadata({ mediaFolderPath: params.mediaFolderPath ?? "" }, userConfig, appDataDir, abortSignal);
    }
  };
}

// ../../apps/core/src/ai-tool/buildGetEpisodesResponse.ts
function createEmptyGetEpisodesData() {
  return {
    episodes: [],
    totalCount: 0,
    showName: "",
    numberOfSeasons: 0
  };
}
function buildGetEpisodesResponse(metadata) {
  const tvShow = metadata.tvShow;
  if (!tvShow) {
    return createEmptyGetEpisodesData();
  }
  const episodeToVideoMap = new Map;
  if (metadata.mediaFiles && Array.isArray(metadata.mediaFiles)) {
    for (const mediaFile of metadata.mediaFiles) {
      if (mediaFile.seasonNumber !== undefined && mediaFile.episodeNumber !== undefined) {
        const key = `${mediaFile.seasonNumber}:${mediaFile.episodeNumber}`;
        episodeToVideoMap.set(key, mediaFile.absolutePath);
      }
    }
  }
  const episodes = [];
  for (const season of tvShow.seasons ?? []) {
    if (season.episodes && Array.isArray(season.episodes)) {
      for (const ep of season.episodes) {
        const key = `${season.season}:${ep.episode}`;
        const videoFilePath = episodeToVideoMap.get(key);
        episodes.push({
          season: season.season,
          episode: ep.episode,
          videoFilePath: videoFilePath ? Path.toPlatformPath(videoFilePath) : undefined
        });
      }
    }
  }
  return {
    episodes,
    totalCount: episodes.length,
    showName: tvShow.name ?? "",
    numberOfSeasons: tvShow.seasons?.length ?? 0
  };
}

