var DEFAULT_USER_CONFIG = {
  folders: [],
  tmdb: {},
  tvdb: {},
  renameRules: [],
  dryRun: false,
  selectedRenameRule: "plex"
};
var fileLocks = new Map;
function resolveUserDataDir(config) {
  return config.hello?.userDataDir ?? config.appDataDir;
}
function userConfigFilePath(userDataDir) {
  return path2.join(userDataDir, "smm.json");
}
async function acquireUserConfigLock(filePath) {
  const previousLock = fileLocks.get(filePath) ?? Promise.resolve();
  let releaseLock;
  const newLock = new Promise((resolve) => {
    releaseLock = resolve;
  });
  fileLocks.set(filePath, newLock);
  try {
    await previousLock;
  } catch {}
  return () => {
    releaseLock();
    if (fileLocks.get(filePath) === newLock) {
      fileLocks.delete(filePath);
    }
  };
}
function isUserConfigFilePath(filePath) {
  const normalized = filePath.replace(/\\/g, "/");
  const base = normalized.slice(normalized.lastIndexOf("/") + 1);
  return base.toLowerCase() === "smm.json";
}
function resolveAppDataDir(config) {
  return config.appDataDir ?? config.hello?.appDataDir;
}
async function readUserConfig(config) {
  const userDataDir = resolveUserDataDir(config);
  if (!userDataDir) {
    return DEFAULT_USER_CONFIG;
  }
  const configPath = path2.join(userDataDir, "smm.json");
  try {
    const content = await readFile3(configPath, "utf-8");
    return JSON.parse(content);
  } catch {
    return DEFAULT_USER_CONFIG;
  }
}
async function isMediaFolderManaged(mediaFolderPath, config) {
  const userConfig = await readUserConfig(config);
  const folders = userConfig.folders ?? [];
  if (folders.length === 0) {
    return false;
  }
  const targetPlatform = Path.toPlatformPath(mediaFolderPath);
  const targetPosix = Path.posix(mediaFolderPath);
  return folders.some((folder) => Path.toPlatformPath(folder) === targetPlatform || Path.posix(folder) === targetPosix);
}
async function readUserConfigDocument(userDataDir) {
  try {
    const content = await readFile3(userConfigFilePath(userDataDir), "utf-8");
    let raw;
    try {
      raw = JSON.parse(content);
    } catch (parseError) {
      const detail = parseError instanceof Error ? parseError.message : "Invalid JSON";
      return { error: `Failed to parse user config: ${detail}` };
    }
    if (raw === null || typeof raw !== "object" || Array.isArray(raw)) {
      return { error: "Failed to parse user config: root value must be an object" };
    }
    const record = raw;
    migrateAIConfig(record);
    return { config: record };
  } catch (error) {
    const code = error.code;
    if (code === "ENOENT") {
      return { config: {} };
    }
    return { error: error instanceof Error ? error.message : "Failed to read user config" };
  }
}
async function writeUserConfigFile(userDataDir, userConfig) {
  await mkdir3(userDataDir, { recursive: true });
  await writeFile3(userConfigFilePath(userDataDir), JSON.stringify(userConfig, null, 2), "utf-8");
}
async function writeUserConfigToDisk(config, userConfig) {
  const userDataDir = resolveUserDataDir(config);
  if (!userDataDir) {
    throw new Error("userDataDir is not configured");
  }
  const release = await acquireUserConfigLock(userConfigFilePath(userDataDir));
  try {
    await writeUserConfigFile(userDataDir, userConfig);
  } finally {
    release();
  }
}

