import os from "node:os";
import { readdir, stat as stat5 } from "node:fs/promises";
import path4 from "node:path";

// src/resolveListFilesPath.ts
import path3 from "node:path";
function joinListFilesChildPath(dirPath, childName) {
  if (dirPath.startsWith("file://")) {
    const separator = dirPath.endsWith("/") ? "" : "/";
    return `${dirPath}${separator}${childName}`;
  }
  return path3.join(dirPath, childName);
}
function resolveListFilesAbsolutePath(folderPath) {
  if (folderPath.startsWith("file://")) {
    return folderPath;
  }
  return path3.resolve(folderPath);
}
function normalizeListFilesInputPath(folderPath) {
  if (folderPath.startsWith("file://")) {
    return folderPath;
  }
  if (folderPath.startsWith("/") && Path.isWindows()) {
    const normalizedPosixPath = folderPath.replace(/^\/([A-Za-z]):\//, "/$1/");
    return Path.win(normalizedPosixPath);
  }
  if (/^[A-Za-z]:/.test(folderPath) && !Path.isWindows()) {
    return new Path(folderPath).abs("posix");
  }
  return Path.toPlatformPath(folderPath);
}

// src/describeToolFailure.ts
function describeToolFailure(error) {
  if (error instanceof Error) {
    return {
      message: error.message,
      errorType: error.constructor.name,
      stack: error.stack,
      raw: String(error)
    };
  }
  if (typeof error === "string") {
    return { message: error, errorType: "string", raw: error };
  }
  if (error === null || error === undefined) {
    return {
      message: "null or undefined thrown",
      errorType: String(error),
      raw: String(error)
    };
  }
  try {
    const json = JSON.stringify(error);
    return {
      message: json && json !== "{}" ? json : String(error),
      errorType: typeof error,
      raw: json ?? String(error)
    };
  } catch {
    return {
      message: String(error),
      errorType: typeof error,
      raw: String(error)
    };
  }
}

// src/listFiles.ts
var listFilesRequestSchema = objectType({
  path: stringType().min(1, "Path is required"),
  onlyFiles: booleanType().optional(),
  onlyFolders: booleanType().optional(),
  includeHiddenFiles: booleanType().optional(),
  recursively: booleanType().optional()
});
var emptyListFilesData = {
  path: "",
  items: [],
  size: 0
};
async function doListFiles(body, config = {}) {
  const { logger, activatePersistedFileAccess } = config;
  const requestId = `listFiles-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
  logger?.info({ requestId, body }, "[ListFiles] request received");
  try {
    const validationResult = listFilesRequestSchema.safeParse(body);
    if (!validationResult.success) {
      logger?.info({ requestId, issues: validationResult.error.issues }, "[ListFiles] validation failed");
      return {
        data: { path: "", items: [], size: 0 },
        error: `Validation Failed: ${validationResult.error.issues.map((i) => i.message).join(", ")}`
      };
    }
    let {
      path: folderPath,
      onlyFiles,
      onlyFolders,
      includeHiddenFiles = false,
      recursively = false
    } = validationResult.data;
    logger?.debug({ requestId, folderPath, onlyFiles, onlyFolders, includeHiddenFiles, recursively }, "[ListFiles] validated params");
    if (folderPath === "~" || folderPath.startsWith("~/")) {
      const homeDir = os.homedir();
      folderPath = folderPath === "~" ? homeDir : path4.join(homeDir, folderPath.slice(2));
    }
    try {
      folderPath = normalizeListFilesInputPath(folderPath);
    } catch (error) {
      logger?.info({ requestId, folderPath, error }, "[ListFiles] Path normalization threw, using raw path");
    }
    const validatedPath = resolveListFilesAbsolutePath(folderPath);
    logger?.info({ requestId, validatedPath }, "[ListFiles] resolved absolute path");
    if (validatedPath.startsWith("file://")) {
      if (activatePersistedFileAccess) {
        try {
          await activatePersistedFileAccess([validatedPath]);
        } catch (error) {
          const failure = describeToolFailure(error);
          logger?.warn({ requestId, validatedPath, ...failure }, "[ListFiles] file access activation failed");
          return {
            data: { path: validatedPath, items: [], size: 0 },
            error: `File Access Activation Failed: ${failure.message}`
          };
        }
      } else {
        logger?.warn({ requestId, validatedPath }, "[ListFiles] file:// path without activatePersistedFileAccess hook");
      }
    }
    try {
      const stats = await stat5(validatedPath);
      logger?.info({ requestId, validatedPath, isDirectory: stats.isDirectory(), isFile: stats.isFile() }, "[ListFiles] stat result");
      if (!stats.isDirectory()) {
        logger?.info({ requestId, validatedPath }, "[ListFiles] path is not a directory");
        return {
          data: { path: validatedPath, items: [], size: 0 },
          error: `Path Not Directory: ${folderPath} is not a directory`
        };
      }
    } catch (error) {
      logger?.info({
        requestId,
        validatedPath,
        folderPath,
        errMessage: error instanceof Error ? error.message : String(error),
        errCode: error instanceof Error ? error.code : undefined
      }, "[ListFiles] stat failed (path not found or not accessible)");
      return {
        data: { path: validatedPath, items: [], size: 0 },
        error: `Directory Not Found: ${folderPath} was not found`
      };
    }
    try {
      logger?.debug({ requestId, validatedPath }, "[ListFiles] starting readdir");
      const results = [];
      let totalCount = 0;
      async function scanDirectory(dirPath, isTopLevel = false) {
        logger?.debug({ requestId, dirPath, isTopLevel }, "[ListFiles] scanDirectory readdir");
        const items = await readdir(dirPath);
        for (const item of items) {
          const fullPath = joinListFilesChildPath(dirPath, item);
          try {
            const itemStats = await stat5(fullPath);
            const isFile = itemStats.isFile();
            const isDirectory = itemStats.isDirectory();
            const filename = path4.basename(item);
            const isHidden = filename.startsWith(".") || filename === "Thumbs.db" || filename === "desktop.ini";
            if (!includeHiddenFiles && isHidden) {
              continue;
            }
            if (isTopLevel) {
              totalCount++;
            }
            let shouldAddToResults = true;
            if (onlyFiles && onlyFolders) {
              shouldAddToResults = isFile;
            } else {
              if (onlyFiles === true && !isFile) {
                shouldAddToResults = false;
              }
              if (onlyFolders === true && !isDirectory) {
                shouldAddToResults = false;
              }
            }
            if (shouldAddToResults) {
              results.push({
                path: fullPath,
                size: itemStats.size,
                mtime: itemStats.mtimeMs,
                isDirectory
              });
            }
            if (isDirectory && recursively) {
              await scanDirectory(fullPath, false);
            }
          } catch {
            continue;
          }
        }
      }
      await scanDirectory(validatedPath, true);
      return {
        data: {
          path: validatedPath,
          items: results,
          size: totalCount
        }
      };
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error));
      const errNo = error?.code;
      logger?.info({
        requestId,
        validatedPath,
        errMessage: err.message,
        errCode: errNo,
        errStack: err.stack
      }, "[ListFiles] readdir/list failed");
      return {
        data: { path: validatedPath, items: [], size: 0 },
        error: `List Directory Failed: ${err.message}`
      };
    }
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error));
    logger?.info({ requestId, errMessage: err.message, errStack: err.stack }, "[ListFiles] unexpected error in doListFiles");
    return {
      data: emptyListFilesData,
      error: `Unexpected Error: ${err.message}`
    };
  }
}

// src/tools/listFilesInMediaFolder.ts
async function executeListFilesInMediaFolder(params, userConfig, abortSignal) {
  if (abortSignal?.aborted) {
    throw new Error("Request was aborted");
  }
  const pathCheck = requireNonEmptyString(params.mediaFolderPath, "mediaFolderPath");
  if (typeof pathCheck !== "string") {
    return {
      ...createEmptyListFilesInMediaFolderData(),
      error: LIST_FILES_IN_MEDIA_FOLDER_INVALID_PATH
    };
  }
  const empty = createEmptyListFilesInMediaFolderData();
  if (!isMediaFolderManagedFromConfig2(userConfig, pathCheck)) {
    return { ...empty, error: LIST_FILES_IN_MEDIA_FOLDER_NOT_MANAGED };
  }
  try {
    const listResult = await doListFiles({
      path: pathCheck,
      recursively: params.recursively ?? true,
      onlyFiles: true
    });
    if (listResult.error) {
      return { ...empty, error: listResult.error };
    }
    const filePaths = listResult.data?.items.filter((item) => !item.isDirectory).map((item) => item.path) ?? [];
    return toolOk(buildListFilesInMediaFolderResponse(filePaths, params.videoFileOnly ?? false));
  } catch (error) {
    return {
      ...empty,
      ...formatToolError(error)
    };
  }
}
function isMediaFolderManagedFromConfig2(userConfig, mediaFolderPath) {
  const targetPlatform = Path.toPlatformPath(mediaFolderPath);
  const targetPosix = Path.posix(mediaFolderPath);
  return (userConfig.folders ?? []).some((folder) => {
    return Path.toPlatformPath(folder) === targetPlatform || Path.posix(folder) === targetPosix;
  });
}
function buildListFilesInMediaFolderTool(userConfig, abortSignal) {
  return {
    description: LIST_FILES_IN_MEDIA_FOLDER_DESCRIPTION,
    inputSchema: listFilesInMediaFolderInputSchema,
    outputSchema: listFilesInMediaFolderOutputSchema,
    execute: async (args) => {
      const params = args ?? {};
      return executeListFilesInMediaFolder({
        mediaFolderPath: params.mediaFolderPath ?? "",
        recursively: params.recursively,
        videoFileOnly: params.videoFileOnly
      }, userConfig, abortSignal);
    }
  };
}

