var listFilesInputSchema = object({
  folderPath: string2().describe("The absolute path of the folder to list files from"),
  recursive: boolean2().optional().default(false).describe("Whether to list files recursively (default: false)"),
  filter: string2().optional().describe("Filter pattern for files/folders (supports wildcards)"),
  videoFileOnly: boolean2().optional().default(false).describe("Whether to return only video files (default: false)")
});
var listFilesOutputSchema = object({
  files: array(string2()).describe("Array of file paths"),
  count: number2().describe("Number of files listed")
});
var TOOL_NAME2 = "list-files";
var TOOL_DESCRIPTION2 = "List all files in a folder. Accepts paths in POSIX or Windows format. " + "Returns plain file paths (no managed-folder check) so this tool is the " + "preferred way for an external AI assistant to inspect a media folder's " + "contents.";
function registerListFilesTool(server, config) {
  const description = config.toolDescriptions?.[TOOL_NAME2] ?? TOOL_DESCRIPTION2;
  server.registerTool(TOOL_NAME2, {
    description,
    inputSchema: listFilesInputSchema,
    outputSchema: listFilesOutputSchema
  }, async (args) => {
    const params = args ?? {};
    const { folderPath, recursive, videoFileOnly } = params;
    if (typeof folderPath !== "string" || folderPath.trim() === "") {
      return createErrorResponse("Invalid path: 'folderPath' must be a non-empty string");
    }
    try {
      const listResult = await doListFiles({
        path: folderPath,
        recursively: recursive ?? false,
        onlyFiles: true
      }, {
        logger: config.logger,
        activatePersistedFileAccess: config.activatePersistedFileAccess
      });
      if (listResult.error) {
        return createErrorResponse(listResult.error);
      }
      const filePaths = listResult.data?.items.filter((item) => !item.isDirectory).map((item) => item.path) ?? [];
      const empty = createEmptyListFilesInMediaFolderData();
      const data = buildListFilesInMediaFolderResponse(filePaths, videoFileOnly ?? false);
      return createSuccessResponse({
        ...empty,
        ...data
      });
    } catch (error) {
      return createErrorResponse(error instanceof Error ? error.message : String(error));
    }
  });
}

